DECLARE
   x   NUMBER;
BEGIN
   FOR r IN (SELECT m_product_id
               FROM m_transaction
              WHERE m_locator_id IN (1000212, 102))
   LOOP
      InventoryCostAllocation (r.m_product_id);
      x := x + 1;

      IF (MOD (x, 100) = 0)
      THEN
         COMMIT;
      END IF;
   END LOOP;

   COMMIT;
END;
